<?php
if (! defined('ABSPATH')) { exit; }
$locale = (string) ($args['locale'] ?? rosa_preview_locale()); $title = (string) ($args['title'] ?? ''); $limit = max(1, (int) ($args['limit'] ?? 4)); $context = (string) ($args['context'] ?? 'latest');
$query = new WP_Query(['post_type'=>'product','post_status'=>'publish','posts_per_page'=>$limit,'orderby'=>$context === 'latest' ? 'date' : 'menu_order date','order'=>'DESC']); $rendered = 0; $families = ['Knives','Scissors','Punches','Chisels','Cutters']; ?>
<section class="rosa-preview-product-section"><div class="rosa-preview-rail"><div class="rosa-preview-section-heading"><h2><?php echo esc_html($title); ?></h2><a href="<?php echo esc_url(home_url($locale === 'ar' ? '/ar/shop/' : '/shop/')); ?>"><?php echo esc_html($locale === 'ar' ? 'عرض الكل' : 'View all'); ?></a></div><div class="rosa-preview-products"><?php while ($query->have_posts()) : $query->the_post(); $product = wc_get_product(get_the_ID()); if ($product instanceof WC_Product) { get_template_part('template-parts/client-preview/product-card', null, ['product'=>$product,'locale'=>$locale]); $rendered++; } endwhile; wp_reset_postdata(); ?><?php for ($i=$rendered; $i<$limit; $i++) : $family=$families[$i % count($families)]; get_template_part('template-parts/client-preview/product-card', null, ['family'=>['label'=>$family,'url'=>home_url($locale === 'ar' ? '/ar/shop/' : '/shop/')],'locale'=>$locale]); endfor; ?></div></div></section>
